 function html(){return '<div class="analysis-head"><span class="analysis-sol">荷重の理論</span><h1>荷重の理論</h1><p>作用の分布から入力を選び、合力・モーメント・仕事を使って、変形と応力へのつながりを確認します。</p></div>'+A.intro({goals:['集中・線・面・慣性・温度荷重を、実物の作用から選ぶ','荷重を節点へ移す理由と、単純な均等割りで起こる誤差を理解する','ケースの選択・組合せを追い、単位・向き・収支から誤りを見分ける'],prerequisites:[['coordinates.html#systems','座標'],['elements.html#element-families','要素の全体像'],['theory.html#boundary','境界条件と拘束']],points:['荷重は大きさだけでなく、方向・位置・分布・単位を決める。','等価節点荷重は、補間した変位に対する仕事を一致させる。','合力とモーメントを確かめた後、変形・応力・荷重分配への感度を調べる。']})+p('最初は1〜8節で荷重の表し方、9〜11節で節点への変換を学びます。自重・回転・温度は12節から、ケースの選択と組合せは18節から進めます。')+A.toc(sections.map(([id,title])=>['load-'+id,title]))+sections.map(([id,title,body],i)=>A.section(`${i+1}. ${title}`,body,'load-'+id)).join('');}
